def __getattr__(name):
    if name not in _EXPORTS:raise AttributeError(name)
    module,attribute=_EXPORTS[name]
    value=getattr(import_module(module,__name__),attribute)
    globals()[name]=value
    return value

def __dir__():
    return sorted(set(globals())|set(__all__))
